  SELECT id INTO route_id_single FROM historical_routes WHERE name = 'Robben Island — Big Bay';
  IF route_id_single IS NULL THEN
    RAISE EXCEPTION 'Route not found: Robben Island — Big Bay';
  END IF;

  INSERT INTO historical_swims
    (source_row_num, swimmer_id, route_id, swim_date, duration,
     distance_km, category, conditions, water_temp_c,
     stroke, is_jammers, is_island_escape, source)
