-- ─── 4. DOUBLE CROSSINGS (BB→RI→BB, 15km) ───────────────────────────────────
DO $$
DECLARE
  route_id_double UUID;
BEGIN
  SELECT id INTO route_id_double FROM historical_routes WHERE name = 'Robben Island Double — Big Bay';
  IF route_id_double IS NULL THEN
    RAISE EXCEPTION 'Route not found: Robben Island Double — Big Bay';
  END IF;

  INSERT INTO historical_swims
    (source_row_num, swimmer_id, route_id, swim_date, duration,
     distance_km, category, conditions, water_temp_c,
     stroke, is_jammers, is_island_escape, source)
  SELECT
    v.row_num, hs.id, route_id_double, v.swim_date::date,
    CASE WHEN v.dur_secs IS NOT NULL THEN (v.dur_secs || ' seconds')::interval ELSE NULL END,
    v.dist_km, v.category, v.conditions, v.temp_c,
    v.stroke, v.jammers, v.island_esc, 'big_bay_swimsummary'
  FROM (VALUES
    (171, 'craig nerwich', NULL, '2014-09-22', 20400, 15.0, 'skins', 'good', 14.0, NULL, false, false),
    (282, 'schalk du plessis', NULL, '2016-04-10', 16380, 15.0, 'skins', 'good', 15.5, NULL, false, false),
    (317, 'karon marx', NULL, '2016-08-04', 24960, 15.0, 'skins', 'choppy', 13.0, NULL, false, false),
